import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();

        // Convert String to StringBuilder for easier modifications
        StringBuilder sb = new StringBuilder(s);

        // Loop to replace 'at' with '@'
        for (int i = 1; i < sb.length() - 1; i++) {
            if (sb.charAt(i) == 'a' && i + 1 < sb.length() && sb.charAt(i + 1) == 't') {
                sb.setCharAt(i, '@');
                sb.deleteCharAt(i + 1);
                break;
            }
        }

        // Loop to replace 'dot' with '.'
        int i = 1;
        while (i < sb.length() - 2) {
            if (sb.charAt(i) == 'd' && sb.charAt(i + 1) == 'o' && sb.charAt(i + 2) == 't') {
                sb.setCharAt(i, '.');
                sb.delete(i + 1, i + 3);
            } else {
                i++;
            }
        }

        System.out.println(sb.toString());
        scanner.close();
    }
}
